"use client";

import { useState } from "react";
import { weatherPresets, PresetKey } from "@/lib/weatherPresets";
import VideoBackground from "@/components/VideoBackground";
import DemoButton from "@/components/DemoButton";

export default function Home() {
  const [demoKey, setDemoKey] = useState<PresetKey | null>("day");
  const data = weatherPresets[demoKey ?? "day"];

  return (
    <main className="relative min-h-screen overflow-hidden text-white">
      <VideoBackground src={data.videoSrc} poster={data.poster} />

      <div className="relative z-[5] p-6 flex flex-col min-h-screen">
        <div className="flex justify-between items-start">
          <span className="text-xs bg-white/15 backdrop-blur-sm px-3 py-1 rounded-full border border-white/30">
            Weather forecast
          </span>
          <DemoButton active={demoKey} onSelect={setDemoKey} />
        </div>

        <div className="mt-auto">
          <h1 className="text-4xl font-semibold mb-2 leading-tight">{data.condition}</h1>
          <p className="text-sm opacity-85 max-w-[420px] mb-5">{data.description}</p>

          <div className="bg-white/15 backdrop-blur-xl border border-white/35 rounded-2xl p-5 flex items-center justify-between">
            <div>
              <p className="text-sm opacity-80 mb-1">Kandy, Sri Lanka</p>
              <p className="text-4xl font-semibold">{data.temp}</p>
            </div>
            <div className="flex gap-4 text-xs opacity-90">
              <span>Humidity {data.humidity}</span>
              <span>Rain {data.precipitation}</span>
              <span>Wind {data.wind}</span>
            </div>
          </div>
        </div>
      </div>
    </main>
  );
}